# Infinia email signatures - sets the signature in Outlook for all 10 mailboxes, shown while typing.
# Run once in PowerShell (pwsh). A Microsoft sign-in window opens: sign in with your admin account.

if (-not (Get-Module -ListAvailable -Name ExchangeOnlineManagement)) { Install-Module ExchangeOnlineManagement -Scope CurrentUser -Force }
Import-Module ExchangeOnlineManagement
Connect-ExchangeOnline -ShowBanner:$false

# Signatures set by the admin only take effect once Outlook "roaming signatures" are postponed for the company.
Set-OrganizationConfig -PostponeRoamingSignaturesUntilLater $true

