foreach ($box in $signatures.Keys) {
  Set-MailboxMessageConfiguration -Identity $box -SignatureHtml $signatures[$box] -AutoAddSignature $true -AutoAddSignatureOnReply $true
  Write-Host "Signature set: $box" -ForegroundColor Green
}

Disconnect-ExchangeOnline -Confirm:$false
Write-Host "Done. Staff may need to refresh Outlook on the web to see it." -ForegroundColor Cyan
